/* Explicit disclosure, no hidden business records or workspace mutations. */
(function(){const previous=render;render=function(){previous();if(!selected)return;const panel=document.querySelector('.detailgrid aside .panel');if(!panel)return;const tasks=[...panel.querySelectorAll('.task')].filter(el=>el.querySelector('input:checked'));if(!tasks.length)return;const disclosure=document.createElement('details');disclosure.className='completed-project-tasks';const label=document.createElement('summary');label.textContent='已完成 '+tasks.length+' 项';disclosure.append(label);tasks.forEach(t=>disclosure.append(t));panel.append(disclosure)}})();
